        "layer1": "8月1日、スイス・ローザンヌ発着137.4km。大会史上2度目の“外国グランデパール”で、締めは石畳の丘プラス・サン＝フランソワへ最後2.6km平均4.6%の上り。純スプリントにはならない設計。",
