        "layer2": "勝ち筋は“モノ売り”からの脱却。あさひでも電動アシスト（+5.6%）・中古（3年で約4倍）・整備が伸び、値引き合戦より『整備・リユース・電アシ・語れる接客』で客単価を残す局面だ。お盆はロングライド需要＝タイヤ／チェーン／ブレーキの“乗る前点検”と、補給・熱中症対策の提案が刺さる。4月からの青切符でライト・反射材・保険の“安全提案”も追い風にできる。",
