        "layer1": "山岳日は誰もが垂れる。初中級が長い登りで脚を残す最短は、重いギアを踏むのでなく“軽いギアを回す”こと。フロント50-34（コンパクト）＋リア11-34や11-36なら、8〜10%の坂でもケイデンス70前後を保ちやすい。",
        "layer2": "目安は「座って回せる最小ギアを一枚残す」こと。ざっくり“ギア比＝斜度%÷10”を下限に用意すると破綻しにくい（例：10%の壁なら比1.0前後＝34T×34T）。ダンシングは筋肉を替えて休むためのフォーム変えに留め、常用しない。現行12速は11-34/11-36のワイドが選べ、機材面でも初中級が「回して登る」構成を組みやすい。今日のオルシエール（7.1km・6.7%）級を自分のロングに置き換えるなら、まずギアから。※数値は一般的な目安、体力・体重・慣れで前後。",
