        "layer1": "2026年4月に始まった自転車の青切符（交通反則通告制度）は施行から約3か月。16歳以上・113種類の違反が対象で、反則金は3,000〜12,000円（ながらスマホが最高額1.2万円）。夏で夜ライドが増える今、無灯火や信号無視は“その場で切符”になり得る。",
        "layer2": "初中級がまず固めるべきは装備の基本——前照灯（白）＋尾灯（赤）の常時点灯、被視認性を上げる反射材、そしてスマホは必ず停車してから。ロードは速度が出るぶん“見えているつもり”でも被視認性が低い。青切符は罰則強化であると同時に「装備と走り方を見直す口実」。3年内に2回摘発されると講習命令（無視で5万円以下の罰金）まである。※制度・金額は警視庁・自治体の公表値。",
