        "layer1": "4月施行の青切符は夏の取り締まりシーズンへ。世間の関心が高いいま、店頭では「違反にならない装備」を入口にした接客が効く。前照灯・尾灯・ベル・反射材・空気圧点検・保険（TSマーク/個人賠責）は、値引き合戦から離れて客単価と信頼を積める領域。",
