        "layer2": "平地の純スプリントは今日の第12ステージでほぼ打ち止め。現在ペデルセン317点、ジルマイ272点、フィリプセン255点。最終週は山岳の中間スプリントが焦点になり、逃げにも乗れるペデルセン有利は動きにくいが、今日ジルマイが勝てば一気に緊迫する。フィリプセンが今大会まだ未勝利なのも波乱要素だ。",
