        "layer1": "本日7/16の第12ステージは179.1kmのほぼ平坦路。フィニッシュ約20km手前のコート・ド・モンタニー＝レ＝ビュクシ（短い上り）が唯一の波乱要素で、基本は『集団スプリント濃厚』。",
