        "layer2": "在庫潤沢・型落ち2〜3割引の買い手市場が一段深化。個人店が横並び値下げの消耗戦に付き合うと体力を削るだけになる。勝ち筋は『目利き（用途に合った1台を絞る）＋アフター（フィッティング・保証・整備）』と、大手が扱いにくいニッチ（中華カーボンの導入支援・組み替え）に寄せること。",
