        "layer2": "初中級の要点は4つ。①コーナー手前で“まっすぐなうちに”減速を終える（傾けてからのブレーキはグリップを失い落車の元）②目線は出口へ（肩・腰が自然に向く）③外足荷重（内ペダルを上げ外足を6時に下ろし体重を乗せる）④集団では前走者の後輪をなぞりラインを外さない。速く曲がるより『安全に曲がって立ち上がりで踏む』が結局速い。",
