        "layer1": "第5ステージ優勝（コーイ）に第6ステージ区間5位（セイシャス）と好調のデカスロンCMA CGMは、2026年から自社ブランド『ヴァンリール』のRCR（オールラウンド）／RCR-F（エアロ）／RCR-X（TT）を、コンポはSRAMワイヤレスに切り替えて走っている。さらにツール会場では、19歳セイシャス向けとみられる“未発表のエアロ試作車”が目撃された。",
