    "greeting": "おはようございます、マサルさん！ 今朝のリサーチ、10本。きょう第6ステージは今大会初のトゥールマレー＆ガヴァルニ初登場の頂上ゴール――『総合の最初の審判』です。昨日はデビュー戦のコーイが混沌のスプリントを制し、トレーエンが黄色を守りました。今日はホイール最前線（スコープの新3本スポーク）と、峠を教材にした初中級2本、市場はプライムデー本番前夜を押さえます。",
