        "layer1": "7/5タラゴナ→バルセロナ168.5km。モンジュイックの激坂3回でUAEが主導権を握り、最後の700m、ポガチャルがアタックした先で同僚イサク・デルトロ（22・メキシコ）を先着させた。ポガチャルは並びかけて手を添え、勝ちを譲った形。デルトロのツール初勝利で、この『譲る』場面がXや国内タイムラインでも一気に拡散した。",
