        "layer1": "帝国データバンクの最新調査は、1ドル160円に迫る円安の長期化と物流・人件費の『粘着的』値上げ圧力を指摘。自転車・機材も例外でなく、輸入完成車・パーツの仕入原価は下げ止まらない。一方で店頭は在庫調整で20〜30%値引きが常態化し、仕入は高い・売値は安いの板挟み。マサルが今夏の発注計画と値付けで意識すべき構造。",
