        "layer2": "完成車が動きにくい今、客単価を支えるのは夏のウェア・冷却小物・補給系といった季節・消耗アイテム。猛暑が本格化する7月を前に、暑熱順化や水分・電解質補給とセットで提案すれば、買い替え需要だけでなく既存客の追加購入を引き出せます。限定品は来店動機そのものにもなります。",
