        "layer1": "タデイ・ポガチャル(UAEチーム・エミレーツXRG)が6/21の最終ステージ(ヴィラール＝シュル＝オロン山頂)で勝利し、自身初のツール・ド・スイス総合優勝を確定。総合2位カラパスに6分32秒差の圧勝だった。",
