        "layer2": "ツール前哨の“スプリンター品定め”。初日はギルマイがメルリールを際どく差し、メルリール陣営は雪辱を期していた。フィリプセンはコーイの発射台の後方に詰まり不発。残るステージで総合は山岳寄りに移り、純スプリンターの首位がどこまで保つかが見どころ。",
