        "status": "確定＝雨天は推奨気圧より下げる方向／曖昧＝最適BARは体重・タイヤ幅で個人差、約0.5BARや前4.2後4.7等の数値はショップ作例の目安で万人共通値ではない ※具体数値は要裏取り"
