        "layer1": "6/15、軽量eバイク用ドライブの新型『TQ HPR60』が登場。ピーク350W・トルク60Nm（先代HPR50比で出力17%・トルク20%増）ながら、モーター単体1.92kg／290Whバッテリー込みシステム3.53kgと『クラス最軽量』を主張する。",
