        "headline": "あさひが減益、新車は買い控え・伸びるのは『修理とパーツ』——『値下げしてる／してない』論争の答え合わせ",
        "layer1": "最大手あさひの2026年2月期は最終減益。物価高の節約志向で新車の買い替え需要が低迷し、一般車・子供車は計画比約1割減。一方で電動アシストの単価増と『部品交換ニーズ』は底堅い、と日経。ブログ・Xでは『2026年、ロードは値下がりしたのか？』論争が続く。",
        "layer2": "確定——あさひ減益と『新車不振・部品交換は底堅い』という構図（日経・あさひIR）。曖昧——純利益の正確な減少率は12月の下方修正報道（純利益約26億・前年比26%減）と通期実績報道（純利益約22.68億・36.2%減）で数字が割れるため※要裏取り（IR短信で確認）。論争の核心は『定価は高止まり・実売は下落』——希望価格は円安・部材高で下がらないが、店頭は型落ち大幅値引きで実質的に買いやすくなった、という構図。マサルへの示唆——完成車の薄利販売だけでは大手と同じく利益が削られる。あさひですら稼ぎ頭が修理・パーツ・電アシに移っているのが市場の答え。個人プロショップの勝ち筋は、値引き競争でなく工賃・フィッティング・メンテ会員化など高粗利サービスへの軸足移動。",
